 24	package com.pousadamarealta.api;
 25	
 26	import io.javalin.Javalin;
 27	import io.javalin.http.Context;
 28	import com.google.gson.Gson;
 29	import com.google.gson.GsonBuilder;
 30	import com.pousadamarealta.database.MessageDao;
 31	import com.pousadamarealta.database.Message;
 32	import com.pousadamarealta.database.RoomDao;
 33	import com.pousadamarealta.domain.Reservation;
