 37	import com.pousadamarealta.api.request.CreateReservationRequest;
 38	import com.pousadamarealta.api.response.*;
 39	
 40	import java.time.LocalDate;
 41	import java.util.*;
 42	import java.sql.SQLException;
 43	
 44	public class Routes {
 45	    private static final Gson gson = new GsonBuilder()
 46	        .serializeNulls()
 47	        .create();
 48	
 49	    public static void setup(Javalin app) {
 50	        app.get("/rooms", ctx -> handleGetRooms(ctx));
 51	        app.post("/reservations", ctx -> handleCreateReservation(ctx));
 52	        app.get("/reservations/{id}", ctx -> handleGetReservation(ctx));
 53	        app.post("/reservations/{id}/confirmation", ctx -> handleConfirmReservation(ctx));
 54	        app.post("/reservations/{id}/cancellation", ctx -> handleCancelReservation(ctx));
 55	        app.post("/reservations/{id}/check-in", ctx -> handleCheckIn(ctx));
 56	        app.post("/reservations/{id}/check-out", ctx -> handleCheckOut(ctx));
 57	        app.get("/reservations/{id}/document", ctx -> handleGetDocument(ctx));
 58	        app.get("/messages", ctx -> handleGetMessages(ctx));
 59	        app.get("/reports/occupancy", ctx -> handleGetOccupancyReport(ctx));
 60	        app.get("/reports/revenue", ctx -> handleGetRevenueReport(ctx));
 61	
 62	        app.exception(ApiException.class, (e, ctx) -> {
 63	            ctx.status(e.getStatusCode());
 64	            ctx.json(new ErrorResponse(e.getErrorCode(), e.getErrorMessage()));
 65	        });
 66	
 67	        app.exception(Exception.class, (e, ctx) -> {
 68	            e.printStackTrace();
 69	            ctx.status(500);
 70	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
 71	        });
 72	    }
 73	
 74	    private static void handleGetRooms(Context ctx) throws SQLException {
 75	        List<Room> rooms = RoomDao.getAllRooms();
 76	        List<RoomResponse> responses = new ArrayList<>();
 77	
 78	        for (Room room : rooms) {
 79	            responses.add(new RoomResponse(
 80	                room.number(),
 81	                room.type().toString(),
 82	                room.capacity(),
 83	                room.nightlyRate()
 84	            ));
 85	        }
 86	
 87	        ctx.json(responses);
 88	    }
 89	
 90	    private static void handleCreateReservation(Context ctx) {
 91	        try {
 92	            CreateReservationRequest request = gson.fromJson(ctx.body(), CreateReservationRequest.class);
 93	            Reservation res = ReservationService.createReservation(request);
 94	            ctx.status(201);
 95	            ctx.json(buildReservationResponse(res));
 96	        } catch (ApiException e) {
 97	            throw e;
 98	        } catch (Exception e) {
 99	            throw new ApiException(400, "INVALID_REQUEST", "Invalid request body");
100	        }
101	    }
102	
103	    private static void handleGetReservation(Context ctx) {
104	        long id = Long.parseLong(ctx.pathParam("id"));
105	        Reservation res = ReservationService.getReservation(id);
106	        ctx.json(buildReservationResponse(res));
107	    }
108	
109	    private static void handleConfirmReservation(Context ctx) {
110	        long id = Long.parseLong(ctx.pathParam("id"));
111	        Reservation res = ReservationService.confirmReservation(id);
112	        ctx.json(buildReservationResponse(res));
113	    }
114	
115	    private static void handleCancelReservation(Context ctx) {
116	        long id = Long.parseLong(ctx.pathParam("id"));
117	        Reservation res = ReservationService.cancelReservation(id);
118	        ctx.json(buildReservationResponse(res));
119	    }
120	
121	    private static void handleCheckIn(Context ctx) {
122	        long id = Long.parseLong(ctx.pathParam("id"));
123	        Reservation res = ReservationService.checkIn(id);
124	        ctx.json(buildReservationResponse(res));
125	    }
126	
127	    private static void handleCheckOut(Context ctx) throws SQLException {
128	        long id = Long.parseLong(ctx.pathParam("id"));
129	        Reservation res = ReservationService.checkOut(id);
130	
131	        Room room = RoomDao.getRoomByNumber(res.getRoomNumber());
132	        VoucherResponse voucher = new VoucherResponse(
133	            res.getId(),
134	            res.getGuestName(),
135	            res.getGuestCpf(),
136	            res.getRoomNumber(),
137	            room.type().toString(),
138	            res.getCheckIn(),
139	            res.getCheckOut(),
140	            res.getNights(),
141	            res.getSubtotal(),
142	            res.getDiscount(),
143	            res.getTotal()
144	        );
145	
146	        ctx.json(voucher);
147	    }
148	
149	    private static void handleGetDocument(Context ctx) throws SQLException {
150	        long id = Long.parseLong(ctx.pathParam("id"));
151	        Reservation res = ReservationService.getReservation(id);
152	
153	        if (res.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
154	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Document is only available for paid reservations");
155	        }
156	
157	        Room room = RoomDao.getRoomByNumber(res.getRoomNumber());
158	        VoucherResponse voucher = new VoucherResponse(
159	            res.getId(),
160	            res.getGuestName(),
161	            res.getGuestCpf(),
162	            res.getRoomNumber(),
163	            room.type().toString(),
164	            res.getCheckIn(),
165	            res.getCheckOut(),
166	            res.getNights(),
167	            res.getSubtotal(),
168	            res.getDiscount(),
169	            res.getTotal()
170	        );
171	
172	        ctx.json(voucher);
173	    }
174	
175	    private static void handleGetMessages(Context ctx) throws SQLException {
176	        List<Message> messages = MessageDao.getAllMessages();
177	        List<MessageResponse> responses = new ArrayList<>();
178	
179	        for (Message msg : messages) {
180	            responses.add(new MessageResponse(msg.id(), msg.channel(), msg.to(), msg.subject(), msg.body()));
181	        }
182	
183	        ctx.json(responses);
184	    }
185	
186	    private static void handleGetOccupancyReport(Context ctx) {
187	        String date = ctx.queryParam("date");
188	        if (date == null) {
189	            throw new ApiException(400, "INVALID_REQUEST", "date parameter is required");
190	        }
191	
192	        String report = ReportService.getOccupancyReport(date);
193	        ctx.header("Content-Type", "text/csv; charset=utf-8");
194	        ctx.result(report);
195	    }
196	
197	    private static void handleGetRevenueReport(Context ctx) {
198	        String month = ctx.queryParam("month");
199	        if (month == null) {
200	            throw new ApiException(400, "INVALID_REQUEST", "month parameter is required");
201	        }
202	
203	        String report = ReportService.getRevenueReport(month);
204	        ctx.header("Content-Type", "text/csv; charset=utf-8");
205	        ctx.result(report);
206	    }
207	
208	    private static ReservationResponse buildReservationResponse(Reservation res) {
209	        return new ReservationResponse(
210	            res.getId(),
211	            res.getRoomNumber(),
212	            res.getGuestName(),
213	            res.getGuestEmail(),
214	            res.getGuestCpf(),
215	            res.getCheckIn(),
216	            res.getCheckOut(),
217	            res.getGuests(),
218	            res.getRatePlan().toString(),
219	            res.getNights(),
220	            res.getSubtotal(),
221	            res.getDiscount(),
222	            res.getTotal(),
223	            res.getStatus().toString(),
224	            res.getAmountPaid(),
225	            res.getRefund()
226	        );
227	    }
228	}
