  1	package com.pousadamarealta.service;
  2	
  3	import com.pousadamarealta.api.ApiException;
  4	import com.pousadamarealta.database.*;
  5	import com.pousadamarealta.domain.*;
  6	import com.pousadamarealta.pricing.*;
  7	import com.pousadamarealta.api.request.CreateReservationRequest;
  8	
  9	import java.math.BigDecimal;
 10	import java.time.LocalDate;
 11	import java.time.format.DateTimeFormatter;
 12	import java.sql.SQLException;
 13	import java.util.List;
 14	
 15	public class ReservationService {
 16	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 17	
 18	    public static Reservation createReservation(CreateReservationRequest request) {
 19	        try {
 20	            validateRequest(request);
 21	
 22	            LocalDate checkIn = LocalDate.parse(request.getCheckIn(), DATE_FORMAT);
 23	            LocalDate checkOut = LocalDate.parse(request.getCheckOut(), DATE_FORMAT);
 24	            RatePlanType ratePlanType = RatePlanType.valueOf(request.getRatePlan());
 25	
 26	            if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
 27	                throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
 28	            }
 29	
 30	            if (request.getGuests() < 1) {
 31	                throw new ApiException(400, "INVALID_REQUEST", "At least 1 guest is required");
 32	            }
 33	
 34	            Room room = RoomDao.getRoomByNumber(request.getRoomNumber());
 35	            if (room == null) {
 36	                throw new ApiException(404, "ROOM_NOT_FOUND", "Room not found");
 37	            }
 38	
 39	            if (request.getGuests() > room.capacity()) {
 40	                throw new ApiException(422, "CAPACITY_EXCEEDED", "Guest count exceeds room capacity");
 41	            }
 42	
 43	            RatePlan ratePlan = RatePlanFactory.createRatePlan(ratePlanType);
 44	            ratePlan.validate(request.getRoomNumber(), checkIn, checkOut, request.getGuests(), request.getCompanyCode());
 45	
 46	            checkRoomAvailability(request.getRoomNumber(), checkIn, checkOut);
 47	
 48	            PriceCalculation price = ratePlan.calculatePrice(room, checkIn, checkOut);
 49	
 50	            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 51	
 52	            long id = ReservationDao.createReservation(
 53	                request.getRoomNumber(),
 54	                request.getGuestName(),
 55	                request.getGuestEmail(),
 56	                request.getGuestCpf(),
 57	                checkIn,
 58	                checkOut,
 59	                request.getGuests(),
 60	                ratePlanType,
 61	                request.getCompanyCode(),
 62	                nights,
 63	                price.subtotal(),
 64	                price.discount(),
 65	                price.total()
 66	            );
 67	
 68	            return ReservationDao.getReservationById(id);
 69	        } catch (SQLException e) {
 70	            throw new RuntimeException("Database error", e);
 71	        } catch (ApiException e) {
 72	            throw e;
 73	        }
 74	    }
 75	
 76	    public static Reservation confirmReservation(long id) {
 77	        try {
 78	            Reservation res = ReservationDao.getReservationById(id);
 79	            if (res == null) {
 80	                throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
 81	            }
 82	
 83	            if (res.getStatus() != ReservationStatus.PENDING) {
 84	                throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed");
 85	            }
 86	
 87	            ReservationDao.updateReservationStatus(id, ReservationStatus.CONFIRMED);
 88	            ReservationDao.updateReservationAmountPaid(id, res.getTotal());
 89	
 90	            sendConfirmationEmail(res);
 91	
 92	            return ReservationDao.getReservationById(id);
 93	        } catch (SQLException e) {
 94	            throw new RuntimeException("Database error", e);
 95	        } catch (ApiException e) {
 96	            throw e;
 97	        }
 98	    }
 99	
100	    public static Reservation checkIn(long id) {
101	        try {
102	            Reservation res = ReservationDao.getReservationById(id);
103	            if (res == null) {
104	                throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
105	            }
106	
107	            if (res.getStatus() != ReservationStatus.CONFIRMED) {
108	                throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only confirmed reservations can check in");
109	            }
110	
111	            ReservationDao.updateReservationStatus(id, ReservationStatus.CHECKED_IN);
112	
113	            return ReservationDao.getReservationById(id);
114	        } catch (SQLException e) {
115	            throw new RuntimeException("Database error", e);
116	        } catch (ApiException e) {
117	            throw e;
118	        }
119	    }
120	
121	    public static Reservation checkOut(long id) {
122	        try {
123	            Reservation res = ReservationDao.getReservationById(id);
124	            if (res == null) {
125	                throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
126	            }
127	
