     1	package com.pousadamarealta.pricing;
     2	
     3	import com.pousadamarealta.domain.Room;
     4	import com.pousadamarealta.api.ApiException;
     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	import java.util.Map;
     8	
     9	public class CorporatePlan implements RatePlan {
    10	    private static final Map<String, BigDecimal> DISCOUNTS = Map.of(
    11	        "TECNOSUL", BigDecimal.valueOf(0.12),
    12	        "AGROVALE", BigDecimal.valueOf(0.18),
    13	        "FARMAVIDA", BigDecimal.valueOf(0.25)
    14	    );
    15	
    16	    private String companyCode;
    17	
    18	    @Override
    19	    public void validate(int roomNumber, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
    20	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    21	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
    22	        }
    23	
    24	        if (companyCode == null || !DISCOUNTS.containsKey(companyCode)) {
    25	            throw new ApiException(400, "INVALID_REQUEST", "Invalid company code");
    26	        }
    27	
    28	        this.companyCode = companyCode;
    29	    }
    30	
    31	    @Override
    32	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut) {
    33	        BigDecimal subtotal = BigDecimal.ZERO;
    34	        LocalDate current = checkIn;
    35	
    36	        while (current.isBefore(checkOut)) {
    37	            BigDecimal nightPrice = room.nightlyRate();
    38	
    39	            if (Season.isHighSeason(current)) {
    40	                nightPrice = nightPrice.multiply(BigDecimal.valueOf(1.20));
    41	            }
    42	
    43	            nightPrice = MoneyRounder.round(nightPrice);
    44	            subtotal = subtotal.add(nightPrice);
    45	            current = current.plusDays(1);
    46	        }
    47	
    48	        subtotal = MoneyRounder.round(subtotal);
    49	        BigDecimal discountRate = DISCOUNTS.get(companyCode);
    50	        BigDecimal discount = MoneyRounder.round(subtotal.multiply(discountRate));
    51	        BigDecimal total = MoneyRounder.round(subtotal.subtract(discount));
    52	
    53	        return new PriceCalculation(subtotal, discount, total);
    54	    }
    55	
    56	    @Override
    57	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    58	        return amountPaid;
    59	    }
    60	}
